try {
  let raw = $json.content || $json.output || $json.text || $json.response || '';
  if (typeof raw !== 'string') raw = JSON.stringify(raw);

  raw = raw.replace(/```json\s*/gi, '').replace(/```/g, '').trim();

  const firstBrace = raw.indexOf('{');
  const lastBrace = raw.lastIndexOf('}');
  if (firstBrace !== -1 && lastBrace !== -1) {
    raw = raw.slice(firstBrace, lastBrace + 1);
  }

  let parsed = JSON.parse(raw);

  parsed = {
    intent: (parsed.intent || 'DIRECT').toString().trim().toUpperCase(),
    location: (parsed.location || '').toString().trim(),
    topic: (parsed.topic || '').toString().trim(),
    timezone: (parsed.timezone || '').toString().trim(),
    expression: (parsed.expression || '').toString().trim(),
  };

  const allowed = ['DIRECT', 'WEATHER', 'NEWS', 'TIME', 'CALCULATOR'];
  if (!allowed.includes(parsed.intent)) parsed.intent = 'DIRECT';

  return [{ json: parsed }];
} catch (error) {
  return [{
    json: {
      intent: 'DIRECT',
      location: '',
      topic: '',
      timezone: '',
      expression: '',
      parsing_error: error.message
    }
  }];
}

