try {
  const topic = (($('Normalizza classificazione').first().json.topic || '') + '').toLowerCase().trim();
  const feedItems = items
    .map(item => item.json)
    .filter(item => item && (item.title || item.link));

  const normalized = feedItems.map(item => {
    const title = (item.title || '').toString();
    const content = (item.contentSnippet || item.content || item.summary || '').toString();
    const link = (item.link || '').toString();
    const dateRaw = item.isoDate || item.pubDate || '';
    const ts = dateRaw ? new Date(dateRaw).getTime() : 0;
    return {
      title,
      content,
      link,
      date: dateRaw,
      ts: Number.isFinite(ts) ? ts : 0
    };
  }).sort((a, b) => b.ts - a.ts);

  let selected = normalized;
  if (topic) {
    const filtered = normalized.filter(item => {
      const hay = `${item.title} ${item.content}`.toLowerCase();
      return hay.includes(topic);
    });
    if (filtered.length > 0) selected = filtered;
  }

  selected = selected.slice(0, 5);

  return [{
    json: {
      topic,
      articles: selected,
      total_found: selected.length
    }
  }];
} catch (error) {
  return [{
    json: {
      topic: '',
      articles: [],
      total_found: 0,
      error: error.message
    }
  }];
}

