try {
  const rawLocation = (($json.location || $json.timezone || '') + '').trim().toLowerCase();
  const mapping = {
    'roma': 'Europe/Rome',
    'rome': 'Europe/Rome',
    'italia': 'Europe/Rome',
    'milano': 'Europe/Rome',
    'milan': 'Europe/Rome',
    'londra': 'Europe/London',
    'london': 'Europe/London',
    'new york': 'America/New_York',
    'newyork': 'America/New_York',
    'tokyo': 'Asia/Tokyo',
    'parigi': 'Europe/Paris',
    'paris': 'Europe/Paris',
    'berlino': 'Europe/Berlin',
    'berlin': 'Europe/Berlin',
    'madrid': 'Europe/Madrid',
    'lisbona': 'Europe/Lisbon',
    'lisbon': 'Europe/Lisbon'
  };

  let timezone = '';
  if (!rawLocation) {
    timezone = 'Europe/Rome';
  } else if (rawLocation.includes('/')) {
    timezone = rawLocation;
  } else {
    timezone = mapping[rawLocation] || '';
  }

  return [{
    json: {
      ...$json,
      requested_location: rawLocation,
      timezone
    }
  }];
} catch (error) {
  return [{
    json: {
      ...$json,
      requested_location: '',
      timezone: '',
      error: error.message
    }
  }];
}

