try {
  let expression = (($json.expression || '') + '').trim().replace(/,/g, '.');

  if (!expression) {
    return [{
      json: {
        ...$json,
        valid: false,
        result: null,
        message: 'Non ho trovato un’espressione matematica da calcolare.'
      }
    }];
  }

  if (!/^[0-9+\-*/().\s]+$/.test(expression) || expression.includes('**') || expression.length > 100) {
    return [{
      json: {
        ...$json,
        valid: false,
        result: null,
        message: 'L’espressione contiene caratteri non consentiti.'
      }
    }];
  }

  const result = Function(`"use strict"; return (${expression})`)();

  if (!Number.isFinite(result)) {
    throw new Error('Il risultato non è numerico.');
  }

  return [{
    json: {
      ...$json,
      valid: true,
      result,
      expression
    }
  }];
} catch (error) {
  return [{
    json: {
      ...$json,
      valid: false,
      result: null,
      message: error.message
    }
  }];
}

